function [names, values, centroidal] = nominal_parameters_UR5e()
%NOMINAL_PARAMETERS_UR5E Nominal parameters of the UR5e Simscape model.
%
%   [names, values] = nominal_parameters_UR5e() returns symbol names and
%   numerical values for every symbol that can appear in theta_base of the
%   ORIGIN-REFERENCED (parallel-axis) model: m_i, Lc_ix/y/z (centre of mass
%   in MDH frame {i}), link dimensions, and Ixx_i..Iyz_i = inertia about the
%   ORIGIN of MDH frame {i}.
%
%   GENERATED by simulink/generate_identification_data.m from the
%   manufacturer description loadrobot('universalUR5e'); do not edit by hand.
%   The centroidal values are expressed in the MDH link frames; the
%   origin-referenced tensor follows from I_o = I_c + m (c'c E3 - c c').

    c.m  = [3.7 8.393 2.275 1.219 1.219 0.1879];
    c.L1 = 0.1625;
    c.L2 = 0.425;
    c.L3 = 0.3922;
    c.L4 = -0.1333;
    c.L5 = -0.0997;
    c.L6 = -0.0996;
    c.LL1 = 0;
    c.LL2 = 0;
    % centre of mass [x y z] of link i in MDH frame {i} (m)
    c.Lc = [0 0 0;0.2125 0 0.138;0.1961 0 0.007000000098;0 0 0;0 0 0;0 0 0.02289999995];
    % centroidal inertia [Ixx Iyy Izz Ixy Ixz Iyz] (kg m^2), MDH frame {i} axes
    c.Ic = [0.01026749589 0.01026749589 0.00666 0 0 0;0.0151074 0.1338857819 0.1338857819 0 0 0;0.004095 0.0312093551 0.0312093551 0 0 0;0.002559898976 0.002559898976 0.0021942 0 0 0;0.002559898976 0.002559898976 0.0021942 0 0 0;9.890410052e-05 9.890410052e-05 0.0001321171875 0 0 0];
    centroidal = c;

    names = {};  values = [];
    for i = 1:6
        Ic = [c.Ic(i,1) c.Ic(i,4) c.Ic(i,5); c.Ic(i,4) c.Ic(i,2) c.Ic(i,6); c.Ic(i,5) c.Ic(i,6) c.Ic(i,3)];
        p  = c.Lc(i,:).';
        Io = Ic + c.m(i)*((p.'*p)*eye(3) - p*p.');      % parallel-axis theorem
        names  = [names, {sprintf('m%d',i), sprintf('Lc%dx',i), sprintf('Lc%dy',i), sprintf('Lc%dz',i), ...
                  sprintf('Ixx%d',i), sprintf('Iyy%d',i), sprintf('Izz%d',i), ...
                  sprintf('Ixy%d',i), sprintf('Ixz%d',i), sprintf('Iyz%d',i)}]; %#ok<AGROW>
        values = [values, c.m(i), c.Lc(i,:), Io(1,1), Io(2,2), Io(3,3), Io(1,2), Io(1,3), Io(2,3)]; %#ok<AGROW>
    end
    names  = [names, {'L1', 'L2', 'L3', 'L4', 'L5', 'L6', 'LL1', 'LL2', 'g'}];
    values = [values, c.L1, c.L2, c.L3, c.L4, c.L5, c.L6, c.LL1, c.LL2, 9.81];
end
